        children: "CREATE OR REPLACE FUNCTION enforcement.accept_case(\n    p_case_id uuid,\n    p_accepted_by text,\n    p_reason_code text,\n    p_command_id text,\n    p_correlation_id text,\n    p_occurred_at timestamptz\n) RETURNS TABLE (\n    case_id uuid,\n    case_number text,\n    new_status text,\n    event_id uuid\n)\nLANGUAGE plpgsql\nAS $$\nDECLARE\n    v_case enforcement.case_file%ROWTYPE;\n    v_event_id uuid := gen_random_uuid();\nBEGIN\n    SELECT * INTO v_case\n    FROM enforcement.case_file cf\n    WHERE cf.id = p_case_id\n    FOR UPDATE;\n\n    IF NOT FOUND THEN\n        RAISE EXCEPTION 'CASE_NOT_FOUND: %', p_case_id;\n    END IF;\n\n    IF v_case.lifecycle_status <> 'SUBMITTED' THEN\n        RAISE EXCEPTION 'INVALID_CASE_STATE: expected SUBMITTED but was %', v_case.lifecycle_status;\n    END IF;\n\n    UPDATE enforcement.case_file\n    SET lifecycle_status = 'ACCEPTED',\n        accepted_at = p_occurred_at,\n        version = version + 1,\n        updated_at = now()\n    WHERE id = p_case_id;\n\n    INSERT INTO enforcement.case_lifecycle_transition (\n        id,\n        case_id,\n        from_status,\n        to_status,\n        transition_reason_code,\n        transitioned_by,\n        transitioned_at,\n        command_id,\n        correlation_id\n    ) VALUES (\n        gen_random_uuid(),\n        p_case_id,\n        v_case.lifecycle_status,\n        'ACCEPTED',\n        p_reason_code,\n        p_accepted_by,\n        p_occurred_at,\n        p_command_id,\n        p_correlation_id\n    );\n\n    INSERT INTO enforcement_event.outbox_event (\n        id,\n        aggregate_type,\n        aggregate_id,\n        aggregate_ref,\n        topic,\n        partition_key,\n        event_type,\n        event_version,\n        payload,\n        correlation_id,\n        causation_id,\n        occurred_at\n    ) VALUES (\n        v_event_id,\n        'CASE',\n        p_case_id,\n        v_case.case_number,\n        'enforcement.case.lifecycle.public.v1',\